import React, { useState, useEffect } from 'react';
import Papa from 'papaparse'; // npm install papaparse
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION
// ==========================================
const BACKEND_URL = 'http://127.0.0.1:8000'; // Django URL
const PRESIGN_ENDPOINT = '/api/s3-presign'; 

// EXACT FILENAMES IN S3
const CSV_FILE = 'forecast_output.csv'; 
const TXT_FILE = 'lime_sentences_manual.txt'; 

const RiverDashboard = () => {
    // State to hold the real data
    const [forecastData, setForecastData] = useState([]);
    const [aiAnalysisLines, setAiAnalysisLines] = useState([]);
    
    // UI State
    const [loading, setLoading] = useState(true);
    const [lastUpdated, setLastUpdated] = useState(null);
    const [error, setError] = useState(null);

    // ==========================================
    // 1. FETCH DATA ENGINE
    // ==========================================
    const fetchData = async () => {
        setLoading(true);
        setError(null);

        try {
            // A. Get Secure URLs from Django
            const getUrl = async (file) => {
                const res = await fetch(`${BACKEND_URL}${PRESIGN_ENDPOINT}?file=${file}`);
                if (!res.ok) throw new Error(`Backend Error for ${file}`);
                const data = await res.json();
                return data.url;
            };

            const csvUrl = await getUrl(CSV_FILE);
            const txtUrl = await getUrl(TXT_FILE);

            // B. Cache Busting (Force fresh download)
            const t = new Date().getTime();
            
            // C. Fetch & Parse CSV (Forecast)
            const csvRes = await fetch(`${csvUrl}&t=${t}`);
            const csvText = await csvRes.text();
            
            Papa.parse(csvText, {
                header: true,
                skipEmptyLines: true,
                complete: (results) => {
                    // Map the specific columns: Timestamp & Predicted_Water_Level
                    const validData = results.data
                        .filter(row => row.Timestamp && row.Predicted_Water_Level)
                        .map(row => ({
                            time: row.Timestamp,
                            level: parseFloat(row.Predicted_Water_Level).toFixed(3) // Keep 3 decimals
                        }))
                        .slice(0, 6); // Take only first 6 rows for "6-Hour Forecast"
                    setForecastData(validData);
                }
            });

            // D. Fetch & Parse TXT (AI Analysis)
            const txtRes = await fetch(`${txtUrl}&t=${t}`);
            const txtData = await txtRes.text();
            const lines = txtData.split('\n').filter(line => line.trim() !== '');
            setAiAnalysisLines(lines);

            setLastUpdated(new Date().toLocaleTimeString());
            setLoading(false);

        } catch (err) {
            console.error("Data Load Error:", err);
            setError("Failed to load live data.");
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
        const interval = setInterval(fetchData, 600000); // Refresh every 10 mins
        return () => clearInterval(interval);
    }, []);

    // ==========================================
    // 2. RENDER (Using your Design)
    // ==========================================
    return (
        <div className="dashboard-wrapper">
            <div className="dashboard-container">
                <header className="dashboard-header">
                    <h1>River Water Level Dashboard</h1>
                    <div className="status-pill">
                        {loading ? '⏳ Syncing...' : `✅ Live: ${lastUpdated}`}
                    </div>
                </header>

                {error && <div className="error-banner">{error}</div>}

                <div className="dashboard-grid">
                    
                    {/* SECTION 1: 6-Hour Water Level Forecast */}
                    <div className="card forecast-card">
                        <div className="card-header">
                            <h2>📊 6-Hour Water Level Forecast</h2>
                        </div>
                        <div className="card-body">
                            {forecastData.length > 0 ? (
                                <div className="table-responsive">
                                    <table className="forecast-table">
                                        <thead>
                                            <tr>
                                                <th>Time Stamp</th>
                                                <th>Predicted Level (m)</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {forecastData.map((row, index) => (
                                                <tr key={index}>
                                                    <td className="time-cell">{row.time}</td>
                                                    <td className="value-cell">
                                                        <strong>{row.level}</strong>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            ) : (
                                <p className="empty-state">Waiting for forecast data...</p>
                            )}
                        </div>
                    </div>

                    {/* SECTION 2: AI Causality Analysis */}
                    <div className="card lime-card">
                        <div className="card-header">
                            <h2>🧠 AI Causality Analysis</h2>
                        </div>
                        <div className="card-body">
                            <div className="lime-list">
                                {aiAnalysisLines.length > 0 ? (
                                    aiAnalysisLines.map((line, index) => {
                                        // Simple icon logic based on keywords
                                        const isIncrease = line.includes('increase') || line.includes('+');
                                        const icon = isIncrease ? '📈' : '📉';
                                        
                                        return (
                                            <div key={index} className="lime-item">
                                                <span className="lime-icon">{icon}</span>
                                                <span className="lime-text">{line}</span>
                                            </div>
                                        );
                                    })
                                ) : (
                                    <p className="empty-state">Waiting for AI analysis...</p>
                                )}
                            </div>
                        </div>
                    </div>

                </div>

                {/* Disclaimer Footer */}
                <footer className="dashboard-footer">
                    <div className="disclaimer-box">
                        <strong>⚠️ DISCLAIMER:</strong> This AI system provides experimental flood risk estimates. 
                        Always follow official alerts from local authorities. 
                        In emergencies, dial <strong>112</strong> or <strong>101</strong>.
                    </div>
                </footer>

                {/* Refresh Button */}
                <button className="fab-refresh" onClick={fetchData} title="Refresh Data">
                    🔄
                </button>
            </div>
        </div>
    );
};

export default RiverDashboard;
